#!/bin/sh
# Refresh build/version.h from the current git HEAD.
#
# version.h is generated by xenia-build.py, not by CMake, so `cmake --build`
# never refreshes it. An incremental build therefore produces a binary whose
# code is current but whose window title and log banner still name whatever
# commit was checked out the last time xenia-build.py ran.
#
# That is not cosmetic here: every benchmark screenshot is labelled with that
# string, and it is the only provenance a capture carries. A stale stamp makes
# a screenshot claim to be a commit it is not.
#
# Run this before an incremental benchmark build.
set -e
BUILD_DIR="${1:-build}"
cd "$(dirname "$0")/../.."
[ -d "$BUILD_DIR" ] || { echo "no such build dir: $BUILD_DIR" >&2; exit 1; }
cat > "$BUILD_DIR/version.h" <<EOH
// Autogenerated by xenia-build.py.
#ifndef GENERATED_VERSION_H_
#define GENERATED_VERSION_H_
#define XE_BUILD_BRANCH "$(git rev-parse --abbrev-ref HEAD)"
#define XE_BUILD_COMMIT "$(git rev-parse HEAD)"
#define XE_BUILD_COMMIT_SHORT "$(git rev-parse --short=9 HEAD)"
#define XE_BUILD_DATE __DATE__
#endif  // GENERATED_VERSION_H_
EOH
echo "version.h -> $(git rev-parse --short=9 HEAD) ($(git rev-parse --abbrev-ref HEAD))"
